INSERT INTO kpi_template (dimension, version, content, active, created_at, updated_at) VALUES
('INDUSTRIALIZATION', '1.0', '{"1":"Aucun versioning, build manuel","2":"Git basique, build local","3":"Git avec branches, build automatise","4":"GitFlow, CI compile et test","5":"CI avec quality gates","6":"CD vers staging automatise","7":"CD vers production semi-auto","8":"CI/CD complet, revue de code systematique","9":"Feature flags, canary deployments","10":"Pipeline mature, observabilite complete"}'::jsonb, true, NOW(), NOW()),
('CODE_QUALITY', '1.0', '{"1":"Aucune regle de codage","2":"Conventions documentees non appliquees","3":"Linter configure non bloquant","4":"Linter bloquant en CI","5":"SonarQube integre, regles definies","6":"Quality gates definis et respectes","7":"Couverture >60 pourcent, dette maitrisee","8":"Couverture >80 pourcent, revues systematiques","9":"Clean code, metriques avancees","10":"Architecture hexagonale, zero dette technique"}'::jsonb, true, NOW(), NOW()),
('TESTING', '1.0', '{"1":"Pas de tests automatises","2":"Quelques tests unitaires adhoc","3":"Tests unitaires >30 pourcent couverture","4":"Tests unitaires >50 pourcent couverture","5":"Tests unitaires et integration >60 pourcent","6":"Pyramide de tests (unit, integ, e2e)","7":"TDD pratique par equipe","8":"Tests de performance inclus","9":"Contract testing entre services","10":"Mutation testing et chaos engineering"}'::jsonb, true, NOW(), NOW()),
('DEPLOYMENT', '1.0', '{"1":"Deploiement manuel serveur physique","2":"Scripts de deploiement basiques","3":"Environnement de recette disponible","4":"Conteneurisation Docker","5":"Docker Compose multi-environnements","6":"Deploiement semi-automatise CI/CD","7":"Orchestration Kubernetes","8":"Blue-green ou rolling updates","9":"GitOps, Infrastructure as Code","10":"Zero-downtime, deploiement continu en prod"}'::jsonb, true, NOW(), NOW()),
('OBSOLESCENCE', '1.0', '{"1":"Dependances obsoletes >3 ans, CVE critiques","2":"Mises a jour ponctuelles, CVE ouvertes","3":"Scan de vulnerabilites periodique","4":"Politique mise a jour trimestrielle","5":"Dependabot/Renovate configure","6":"Mises a jour mensuelles planifiees","7":"Zero CVE critique, LTS suivies","8":"Migration proactive frameworks","9":"Veille technologique structuree","10":"Evergreen: stack toujours a jour"}'::jsonb, true, NOW(), NOW()),
('AI_ADOPTION', '1.0', '{"1":"Aucune utilisation IA","2":"Usage ponctuel ChatGPT individuel","3":"Copilot adopte par quelques devs","4":"IA integree au workflow quotidien","5":"Generation de code assistee IA","6":"Tests et documentation generes par IA","7":"Revue de code par agents IA","8":"Refactoring automatise par IA","9":"Orchestration multi-agents dev","10":"IA pilotant architecture et decisions"}'::jsonb, true, NOW(), NOW());
